import type { CameraInfo } from './features/handFrame';
import { ALL_FEATURES } from './xrFeatures';

const enterButton = document.querySelector<HTMLButtonElement>('#enter')!;
const message = document.querySelector<HTMLParagraphElement>('#message')!;
const tableBody = document.querySelector<HTMLTableSectionElement>('#support tbody')!;
const statusCells = new Map<string, HTMLTableCellElement>();
/** 前回選んだカメラの deviceId を覚えておく localStorage のキー */
const CAMERA_KEY = 'mr-playroom/camera';

for (const feature of ALL_FEATURES) {
  const row = tableBody.insertRow();
  row.insertCell().innerHTML = `${feature.label}<br><code>${feature.id}</code>`;
  row.insertCell().textContent = feature.use;
  const status = row.insertCell();
  status.textContent = '未確認';
  statusCells.set(feature.id, status);
}

export function setMessage(text: string): void {
  message.textContent = text;
}

/** immersive-ar が使えるかを調べ、使えるときだけ開始ボタンを有効にする。 */
export async function setupEnterButton(onEnter: () => void): Promise<void> {
  enterButton.addEventListener('click', onEnter);
  if (!navigator.xr) {
    setMessage('このブラウザは WebXR に対応していません。Meta Quest のブラウザで、HTTPS で開いてください。');
    return;
  }
  // 確認に時間がかかる環境があるので、その間も何が起きているか分かるようにする。
  setMessage('MR に対応しているか確認しています…');
  const supported = await navigator.xr.isSessionSupported('immersive-ar').catch(() => false);
  if (!supported) {
    setMessage('このデバイスは immersive-ar (パススルー MR) セッションに対応していません。');
    return;
  }
  setMessage('');
  enterButton.disabled = false;
}

/**
 * カメラの許可ボタン。許可のダイアログは MR セッション中には出せないので、開始前に押してもらう。
 * 取れた映像はページに表示し、どのカメラが使われているかを目で確かめられるようにする。
 * onRequest は、deviceId のカメラ (省略時はおまかせ) の映像を取り始める。使えなければ null を返す。
 */
export function setupCameraButton(onRequest: (deviceId?: string) => Promise<CameraInfo | null>): void {
  const button = document.querySelector<HTMLButtonElement>('#camera')!;
  const status = document.querySelector<HTMLSpanElement>('#camera-status')!;
  const preview = document.querySelector<HTMLDivElement>('#camera-preview')!;
  const select = document.querySelector<HTMLSelectElement>('#camera-select')!;

  const request = (deviceId?: string): void => {
    button.disabled = true;
    select.disabled = true;
    status.textContent = 'カメラの映像を待っています…';
    onRequest(deviceId)
      // 覚えていたカメラが無くなっていた場合は、おまかせで選び直す。
      .catch((error: unknown) => (deviceId ? onRequest() : Promise.reject(error)))
      .then(
        (info) => {
          if (!info) {
            status.textContent = 'このブラウザではカメラを使えません。写真は仮想物体だけになります。';
            return;
          }
          const { video, cameras } = info;
          status.textContent = `カメラを使えます (${video.videoWidth}×${video.videoHeight})。`;
          select.replaceChildren(...cameras.map((camera) => new Option(camera.label, camera.deviceId)));
          select.value = info.deviceId;
          preview.querySelector('video')?.remove();
          preview.append(video);
          preview.hidden = false;
        },
        (error: unknown) => {
          console.error(error);
          button.disabled = false;
          status.textContent = `カメラを使えませんでした: ${error instanceof Error ? error.message : String(error)}`;
        },
      )
      .finally(() => (select.disabled = false));
  };
  // Quest のブラウザは、既定ではアバターを映す仮想カメラを選ぶ。名前からは見分けられないので、
  // 一度選んでもらったカメラを覚えておき、次回からはそれを使う。
  button.addEventListener('click', () => request(localStorage.getItem(CAMERA_KEY) ?? undefined));
  select.addEventListener('change', () => {
    localStorage.setItem(CAMERA_KEY, select.value);
    request(select.value);
  });
}

/** 撮った写真を一覧に足す。押すと保存できる。 */
export function addPhoto(url: string, name: string): void {
  document.querySelector<HTMLElement>('#gallery')!.hidden = false;
  const link = document.createElement('a');
  link.href = url;
  link.download = name;
  const image = document.createElement('img');
  image.src = url;
  image.alt = name;
  link.append(image);
  document.querySelector<HTMLDivElement>('#photos')!.append(link);
}

/** セッションが実際に有効化した機能を一覧に反映する。 */
export function showEnabledFeatures(enabled: readonly string[] | undefined): void {
  for (const [id, cell] of statusCells) {
    if (!enabled) {
      cell.textContent = '不明';
      cell.className = '';
      continue;
    }
    const ok = enabled.includes(id);
    cell.textContent = ok ? '有効' : '非対応';
    cell.className = ok ? 'ok' : 'ng';
  }
}
import { App } from './app';
import { Audio } from './features/audio';
import { Cursors } from './features/cursors';
import { DepthColliders } from './features/depthColliders';
import { DepthView } from './features/depthView';
import { Drawing } from './features/drawing';
import { HandColliders } from './features/handColliders';
import { HandFrame } from './features/handFrame';
import { HitTest } from './features/hitTest';
import { Lighting } from './features/lighting';
import { Occlusion } from './features/occlusion';
import { Placement } from './features/placement';
import { Portal } from './features/portal';
import { Room } from './features/room';
import { StatusPanel } from './features/statusPanel';
import { Toys } from './features/toys';
import type { HandState } from './input';
import { addPhoto, setMessage, setupCameraButton, setupEnterButton, showEnabledFeatures } from './landing';

const app = new App();
await app.physics.init();

const lighting = app.add(new Lighting(app));
const occlusion = app.add(new Occlusion(app));
app.add(new Cursors(app));
const room = app.add(new Room(app));
app.add(new HandColliders(app, room));
const depthColliders = app.add(new DepthColliders(app, room));
const depthView = app.add(new DepthView(app));
const toys = app.add(new Toys(app));
const hitTest = app.add(new HitTest(app));
const placement = app.add(new Placement(app, hitTest));
const drawing = app.add(new Drawing(app));
const portal = app.add(new Portal(app, hitTest));
const handFrame = app.add(new HandFrame(app));

const audio = app.add(new Audio());
toys.onImpact = (position, speed, kind) => audio.impact(position, speed, kind);
app.menu.onPress = (position) => audio.click(position);
placement.onPlaced = (position) => audio.chime(position);
portal.onOpened = (position) => audio.chime(position);
handFrame.onCapture = (position) => audio.click(position);
handFrame.onPhoto = (photo) => addPhoto(photo.url, photo.name);
setupCameraButton((deviceId) => handFrame.startCamera(deviceId));

const status = app.add(new StatusPanel(app));
const describeHand = (hand: HandState): string => (!hand.tracked ? 'なし' : hand.isHand ? '素手' : 'コントローラー');
status.setDetail('local-floor', () => `目の高さ ${app.camera.position.y.toFixed(2)} m`);
status.setDetail('hand-tracking', () => `左: ${describeHand(app.input.left)} / 右: ${describeHand(app.input.right)}`);
status.setDetail('plane-detection', () => `${room.planeCount} 面`);
status.setDetail('mesh-detection', () => `${room.meshCount} 個`);
status.setDetail('hit-test', () => (hitTest.usingFallback ? '使えないため y=0 の床で代用' : '配置・ポータルの照準'));
status.setDetail('anchors', () => {
  const failures = placement.persistFailures > 0 ? `、保存失敗 ${placement.persistFailures}` : '';
  return `${placement.anchoredCount} 個 (うち保存 ${placement.persistentCount}${failures})`;
});
// 失敗の理由が長くなるので、行ではなく、パネルの幅いっぱいの注記に出す。
status.setNote(() => app.persistence.status);
status.setDetail('depth-sensing', () => {
  if (!occlusion.active) return '深度データなし';
  const state = !occlusion.enabled ? '受信中 (遮蔽オフ)' : occlusion.soft ? '遮蔽中 (ぼかし)' : '遮蔽中 (くっきり)';
  const view = depthView.enabled ? ' / 深度だけ表示中' : '';
  return (depthColliders.enabled ? `${state} / 当たり判定 ${depthColliders.count} 面` : state) + view;
});
status.setDetail('light-estimation', () => (lighting.estimating ? '推定値を照明に反映中' : '固定の照明'));
status.setFooter(
  () =>
    `おもちゃ ${toys.count} / 配置 ${placement.count} / 線 ${drawing.count} / ポータル ${portal.count}` +
    ` / 写真 ${handFrame.photos.length} (${
      handFrame.cameraLive ? 'カメラ映像あり' : handFrame.cameraReady ? 'カメラ映像が止まっている' : 'カメラなし'
    })`,
);

app.menu.addAction('全部消す', () => app.clearAll());
// 物理は最後に進める。各機能がこのフレームの入力を物体に反映してから計算するため。
app.add(app.physics);

app.onSessionStart = (session) => {
  setMessage('');
  showEnabledFeatures(session.enabledFeatures);
};

void setupEnterButton(() => {
  audio.unlock();
  app.enterXR().catch((error: unknown) => {
    console.error(error);
    setMessage(`MR セッションを開始できませんでした: ${error instanceof Error ? error.message : String(error)}`);
  });
});

# MR プレイルーム

WebXR の複合現実 (MR) 機能をひととおり試すためのサンドボックスです。Meta Quest 3 のブラウザを対象にしています。
自分の部屋の中で、機能ごとの「おもちゃ」を切り替えて遊べます。

## 起動

[Deno](https://deno.com/) 2 が必要です (Node.js は不要です)。

```sh
deno install     # 依存パッケージを取得
deno task dev    # 開発サーバーを起動
```

WebXR は HTTPS か localhost でしか動かないため、開発サーバーは自己署名証明書の HTTPS で起動します。

1. PC と Quest を同じネットワークにつなぎます。
2. 起動時に表示される `Network:` の URL (例: `https://192.168.x.x:5173/`) を Quest のブラウザで開きます。
3. 証明書の警告が出るので、「詳細設定」から続行します。
4. 「MR を開始」を押します。

床・壁・机を使う機能は、Quest の「スペースのセットアップ」が済んでいる部屋で動きます。
未設定の場合は、メニューの「部屋をスキャン」から呼び出せます。

そのほかのコマンド:

```sh
deno task build      # 型チェックと本番ビルド (dist/)
deno task typecheck  # 型チェックのみ
```

## 操作

素手 (ハンドトラッキング) とコントローラーのどちらでも操作できます。

| 操作 | 素手 | コントローラー |
|---|---|---|
| 道具を使う | つまむ (親指と人差し指) | トリガー |
| 近くの物をつかむ | 物の近くでつまむ、または手全体で握る | グリップ、またはトリガー |
| メニューを出す | 左手のひらを上に向ける | 左手のひらを上に向ける (コントローラーを外側へ倒す) |
| メニューを押す | 右手の人差し指で押す | 右のレイを当ててトリガー |

つかめるのは、ボール・ブロックと、撮った写真、描いた線です。写真と線は、離すとその場に浮いたまま残ります。
重なっている線は、ひとつの絵としてまとめて動きます。
持っている写真や線をもう一方の手でも持つと、ブロックと同じように、手の間隔で拡大縮小、手の向きで回転します。
「お絵描き」を選んでいる間は、つまみ / トリガーは描くことに使うので、写真や線を持つには手全体で握ります
(コントローラーではグリップ)。

手全体で握る動きは、人差し指から小指までの 4 本がすべて曲がっていることで判定します。握っている手では、
つまみは働きません (握ったときに親指が人差し指に触れても、道具は発動しません)。

メニューは、左手のひらを上に向けている間だけ左手の上に出ます。左手が見つからないときは、正面に固定で表示されます。

### 道具

| 道具 | できること |
|---|---|
| ボール | 手の中に出して、離すと投げられる。現実の床・壁・机で跳ね返る |
| ブロック | 出して積める。両手でつかむと、手の間隔で拡大縮小、手の向きで回転 |
| 配置 | レイで指した面に物を置く。床や机には植物・ランプ・積み木、壁には絵。次回起動時も同じ場所に残る |
| お絵描き | つまんだまま (トリガーを引いたまま) 動かすと、空中に線が残る |
| ポータル | レイで指した壁や床に、別の世界が覗ける穴を開ける (3 つまで) |

### 手で写真を撮る

道具の選択に関係なく、素手のときはいつでも使えます (コントローラーでは使えません)。

1. 両手の親指と人差し指をそれぞれ L 字に開き、互い違いに向かい合わせて四角を作ります
   (片方の人差し指は上、もう片方は下向き)。その形を少し保つと、白い枠が出ます。
2. どちらかの親指を人差し指の付け根へ倒すと、枠の中に見えている範囲が写真になります。
3. 写真は撮った枠の位置に、枠と同じ大きさで浮かんで残り、つまんで持ち運べます。MR を終了すると、ページの「撮った写真」から保存できます。

枠は、人差し指を曲げる、前に向ける、手を下ろす、のどれかで消えます。

現実の景色も写すには、MR を開始する前に、ページの「カメラを許可」を押してください。
ボタンの下にカメラの映像が出るので、目の前の景色が映っていることを確かめます。
違うもの (アバターなど) が映っている場合は、その上の一覧から別のカメラを選びます。
許可しない場合は、仮想物体だけが暗い背景の上に写ります。

### 空間の保存

ボール・ブロック・線・ポータル・空間に残した写真は、数秒おきに自動で保存されます。
ページを閉じても、次に同じ部屋で MR を開始すると、現実の同じ場所に戻ります (配置した物は、以前から個別に保存されています)。

- 戻したボールとブロックは、その場で止まった状態で現れます。つかむか、何かが当たると動き出します。
- 保存の状況は、状態パネルのいちばん下に出ます。失敗したときは、どの段階 (作成・永続化・復元) で
  何が起きたかと、このサイトが持っている永続アンカーの数も出ます。
- 前回の場所が見つからないとき (別の部屋で開いたなど) は、元の部屋の内容を上書きしないよう、保存を止めます。
  元の部屋に戻れば復元されます。いまの場所で新しく始めるには、「全部消す」を押します (前回の内容は消えます)。
- 保存先はこのブラウザの中 (localStorage と IndexedDB) です。サイトのデータを消すと、保存も消えます。

### 表示の切り替え

| 項目 | 内容 |
|---|---|
| 影 | 仮想物体の影を、現実の床や机に落とす |
| 遮蔽 | 現実の物や自分の手で、仮想物体を隠す |
| 遮蔽をぼかす | オン: 輪郭をなめらかに薄くする (チラつきが少ないが重い) / オフ: 画素ごとにくっきり隠す |
| 手で撮影 | 両手で作った枠で写真を撮る機能を有効にする |
| 手で押す | 自分の手 (素手の関節、コントローラー) でボールやブロックを押したり叩いたりできるようにする |
| 深度で当たる | 深度センサーで見えた物 (部屋のスキャン後に動かした物や人) にもボールやブロックが当たる。「部屋の形」がオンなら、当たり判定の面をオレンジの網目で表示する |
| 部屋の形 | 検出された平面・メッシュと、その種類 (床、壁、机など) を表示する。手と深度の当たり判定も表示する |
| 状態パネル | 各 WebXR 機能が有効か、いま何が取れているかを表示する |

「全部消す」は、おもちゃ・配置した物 (保存したアンカーを含む)・線・ポータルをすべて消します。

## WebXR の機能とコードの対応

機能ごとにファイルを分けてあります。どの API がどう使われているかは、各ファイルの冒頭のコメントから読めます。

| WebXR の機能 | 用途 | コード |
|---|---|---|
| `immersive-ar` セッション | パススルー映像の上に描画する | `src/app.ts` |
| 入力 (`XRInputSource`) | 素手とコントローラーを同じ形で扱う | `src/input.ts` |
| `hand-tracking` | 指先・手首の関節の姿勢を読む。握る動きの判定にも使う | `src/input.ts` |
| `hand-tracking` (関節の半径) | 関節ごとの球で、手を物理の当たり判定にする | `src/features/handColliders.ts` |
| `plane-detection` / `mesh-detection` | 部屋の形の表示、物理の当たり判定、影を受ける面 | `src/features/room.ts` |
| `hit-test` | レイと現実の面の交点 | `src/features/hitTest.ts` |
| `anchors` (永続アンカーを含む) | 置いた物を現実の位置に固定し、次回も復元する | `src/features/placement.ts` |
| `anchors` (永続アンカー) | 部屋の基準を 1 つ置き、そこから見た位置で空間の物を保存・復元する | `src/features/persistence.ts` |
| `depth-sensing` | 現実の物による遮蔽 | `src/features/occlusion.ts` |
| `depth-sensing` (GPU からの読み出し) | 後から動かした物や人の当たり判定 | `src/features/depthColliders.ts` |
| `light-estimation` | 現実の光源に照明を合わせる | `src/features/lighting.ts` |
| ハプティクス (`Gamepad.hapticActuators`) | つかむ・置く・押すときの振動 | `src/input.ts` の `pulse()` |

WebXR 以外で組み合わせているもの:

| 技術 | 用途 | コード |
|---|---|---|
| Rapier (物理エンジン) | ボールとブロックの物理 | `src/physics.ts`、`src/features/toys.ts` |
| ステンシルバッファ | ポータルの穴の切り抜き | `src/features/portal.ts` |
| Web Audio API (HRTF) | 衝突音などの空間音響 | `src/features/audio.ts` |
| キャンバステクスチャ | 空間内のメニューとパネル | `src/ui/canvasPanel.ts` |
| レンダーターゲット、`getUserMedia` | 手の枠で撮る写真 (仮想物体の描画と、パススルーカメラの映像の合成) | `src/features/handFrame.ts` |

## 構成

- `src/app.ts`: セッションの開始と、毎フレームの処理。機能は `Feature` として登録し、1 つが例外を出しても他は動き続けます。
- `src/tools.ts`: つまみ / トリガーの行き先 (メニュー → 近くの物をつかむ → 選択中の道具) を決めます。
- `src/features/holding.ts`: 写真や線など、物理を持たない物を手で持って動かします。持てる物は各機能が登録します。
- `src/features/`: 機能ごとの実装。メニューのボタンは各機能が自分で登録します。

## 制約

- Quest 3 のブラウザは、執筆時点で `light-estimation` に対応していません。その場合は固定の照明になります。
  対応状況は状態パネルで確認できます。
- 遮蔽は深度センサーの解像度と誤差の影響を受けます。現実の面に接している仮想物体は、縁が欠けて見えることがあります。
- 写真の中の現実の景色は、パススルーカメラの映像を仮の画角 (`handFrame.ts` の `CAMERA_FOV_HORIZONTAL`) で
  切り出しています。枠から見えた範囲と、位置や大きさがずれることがあります。
  また、写真には遮蔽が反映されません (現実の物の後ろにある仮想物体も写ります)。
- 永続アンカーには個数の上限があります。上限を超えた物は、そのセッション中だけ有効です
  (状態パネルに「保存失敗」として出ます)。空間の保存も永続アンカーを 1 つ使うので、配置した物が上限まで
  使っていると、空間を保存できません (「空間: 保存できません」と出ます)。
- 空間の物は、保存したときと復元したときの基準アンカーの位置から計算し直しています。
  部屋の認識のずれによって、数 cm ずれて戻ることがあります。
- ポータルは色合いだけを保存します。中の世界の物の色や星の位置は、復元のたびに少し変わります。
